WITH event_rows AS (SELECT mktcode,tgtcode,bizdate,closePx,MAX(closePx) OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate ROWS BETWEEN 79 PRECEDING AND CURRENT ROW) AS rolling_high FROM `newzl`.`hsj_stock_hq_basic`), recent_events AS (SELECT DISTINCT mktcode,tgtcode FROM event_rows WHERE closePx>=rolling_high AND bizdate IN (SELECT bizdate FROM `newzl`.`hsj_stock_hq_basic` GROUP BY bizdate ORDER BY bizdate DESC LIMIT 3)) SELECT b.mktcode,b.tgtcode,b.bizdate FROM `newzl`.`hsj_stock_hq_basic` b JOIN recent_events e ON e.mktcode=b.mktcode AND e.tgtcode=b.tgtcode WHERE b.bizdate='2026-04-14' AND b.closePx/10000.0<10;
